-- Tenant membership and row-level security baseline. Review alongside the core schema before applying.
create table if not exists public.company_memberships(
 id uuid primary key default gen_random_uuid(),
 company_id uuid not null references public.companies(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 role text not null check(role in('owner','admin','manager','staff','viewer')),
 created_at timestamptz not null default now(),
 unique(company_id,user_id)
);
alter table public.company_memberships enable row level security;
create policy "members can read own memberships" on public.company_memberships for select using(user_id=auth.uid());
create policy "company admins manage memberships" on public.company_memberships for all
 using(exists(select 1 from public.company_memberships m where m.company_id=company_memberships.company_id and m.user_id=auth.uid() and m.role in('owner','admin')))
 with check(exists(select 1 from public.company_memberships m where m.company_id=company_memberships.company_id and m.user_id=auth.uid() and m.role in('owner','admin')));
\nalter table public.branches enable row level security;\ncreate policy "tenant members access branches" on public.branches for all using (exists(select 1 from public.company_memberships m where m.company_id=branches.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=branches.company_id and m.user_id=auth.uid()));\n\nalter table public.borrowers enable row level security;\ncreate policy "tenant members access borrowers" on public.borrowers for all using (exists(select 1 from public.company_memberships m where m.company_id=borrowers.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=borrowers.company_id and m.user_id=auth.uid()));\n\nalter table public.loan_products enable row level security;\ncreate policy "tenant members access loan_products" on public.loan_products for all using (exists(select 1 from public.company_memberships m where m.company_id=loan_products.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=loan_products.company_id and m.user_id=auth.uid()));\n\nalter table public.loan_applications enable row level security;\ncreate policy "tenant members access loan_applications" on public.loan_applications for all using (exists(select 1 from public.company_memberships m where m.company_id=loan_applications.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=loan_applications.company_id and m.user_id=auth.uid()));\n\nalter table public.loans enable row level security;\ncreate policy "tenant members access loans" on public.loans for all using (exists(select 1 from public.company_memberships m where m.company_id=(select a.company_id from public.loan_applications a where a.id=loans.application_id) and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=(select a.company_id from public.loan_applications a where a.id=loans.application_id and m.user_id=auth.uid()));\n\nalter table public.loan_transactions enable row level security;\ncreate policy "tenant members access loan_transactions" on public.loan_transactions for all using (exists(select 1 from public.company_memberships m where m.company_id=(select l.company_id from public.loans l where l.id=loan_transactions.loan_id) and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=(select l.company_id from public.loans l where l.id=loan_transactions.loan_id) and m.user_id=auth.uid()));\n\nalter table public.audit_events enable row level security;\ncreate policy "tenant members access audit_events" on public.audit_events for all using (exists(select 1 from public.company_memberships m where m.company_id=audit_events.company_id and m.user_id=auth.uid())) with check (exists(select 1 from public.company_memberships m where m.company_id=audit_events.company_id and m.user_id=auth.uid()));\n